KEYWORDS = {'let', 'print'}
def tokenize(src):
    tokens = []
    i, n = 0, len(src)
    while i < n:
        char = src[i]
        if char.isspace():
            i += 1
        elif char.isdigit():
            start = i
            while i < n and src[i].isdigit(): i += 1
            tokens.append(('NUM', src[start:i]))
        elif char.isalpha() or char == '_':
            start = i
            while i < n and (src[i].isalnum() or src[i] == '_'): i += 1
            word = src[start:i]
            tokens.append(('KEYWORD' if word in KEYWORDS else 'ID', word))
        elif char in '+-*/=':
            tokens.append(('OP', char))
            i += 1
        elif char == '(':
            tokens.append(('LPAREN', char))
            i += 1
        elif char == ')':
            tokens.append(('RPAREN', char))
            i += 1
        else:
            tokens.append(('ERROR', char))
            i += 1
    return tokens
print(tokenize('let x = 42'))

